    function initResearchHome() {
        var modeBar = document.getElementById('bot-mode-bar');
        var chipsWrap = document.getElementById('quick-suggest-chips');
        var chipsLabel = document.getElementById('qchips-label');
        if (!modeBar || !chipsWrap) return;

        // মোড বাটন ক্লিক
        var modeBtns = modeBar.querySelectorAll('.bot-mode-btn');
        modeBtns.forEach(function(btn) {
            btn.addEventListener('click', function() {
                modeBtns.forEach(function(b) { b.classList.remove('active'); });
                btn.classList.add('active');
                RH.currentMode = btn.getAttribute('data-bmode') || 'general';
                renderChips();
                var inp = document.getElementById('chat-input');
                if (inp) inp.placeholder = RH.placeholders[RH.currentMode] || 'অনুসন্ধান করুন...';
            });
        });

        renderChips();

        // চিপ ক্লিক → ইনপুটে বসিয়ে পাঠাও
        chipsWrap.addEventListener('click', function(e) {
            var btn = e.target.closest('button');
            if (!btn) return;
            var inp = document.getElementById('chat-input');
            if (inp) {
                inp.value = btn.textContent;
                inp.focus();
                showTerminalPreview(btn.textContent);
                var sendBtn = document.getElementById('send-btn');
                if (sendBtn) setTimeout(function() { sendBtn.click(); }, 400);
            }
        });

        // ডেটা লোড হলে ds-pill আপডেট
        setTimeout(function() { setDsPill('ds-tf', 'active'); }, 3000);
        setTimeout(function() { setDsPill('ds-en', 'active'); }, 4500);
        setTimeout(function() { setDsPill('ds-wbw', 'active'); }, 6000);
    }

    function renderChips() {
        var wrap = document.getElementById('quick-suggest-chips');
        var label = document.getElementById('qchips-label');
        if (!wrap) return;
        var list = RH.chips[RH.currentMode] || [];
        wrap.innerHTML = list.map(function(c) {
            return '<button>' + c + '</button>';
        }).join('');
        if (label) label.textContent = RH.labels[RH.currentMode] || 'প্রস্তাবিত প্রশ্ন';
    }

    function setDsPill(id, state) {
        var pill = document.getElementById(id);
        if (!pill) return;
        pill.className = 'ds-pill ' + state;
        var dot = pill.querySelector('.ds-dot');
        if (dot) dot.style.background = state === 'active' ? '#2db85a' : state === 'loading' ? 'var(--gold)' : '#b0c4b0';
    }

    function showTerminalPreview(query) {
        var ra = document.getElementById('research-result-area');
        var rb = document.getElementById('rra-body');
        var rs = document.getElementById('rra-sources');
        var rt = document.getElementById('rra-title');
        if (!ra || !rb) return;
        ra.classList.add('show');
        var data = RH.terminalData[RH.currentMode] || RH.terminalData.general;
        if (rt) rt.textContent = data.title;
        rb.innerHTML = '<span class="rra-cursor"/>';
        if (rs) rs.innerHTML = '';
        var lines = data.body.split('\n'), i = 0, out = '';
        function typeNext() {
            if (i < lines.length) {
                out += (i > 0 ? '\n' : '') + lines[i++];
                rb.textContent = out;
                setTimeout(typeNext, 70);
            } else if (rs) {
                rs.innerHTML = data.srcs.map(function(s) {
                    return '<span class="rra-src-tag">📂 ' + s + '</span>';
                }).join('');
            }
        }
        setTimeout(typeNext, 100);
        // চ্যাট স্ক্রোল এরিয়া সরিয়ে নিচে নামাও
        setTimeout(function() {
            var chatScroll = document.getElementById('chat-scroll-area');
            if (chatScroll) chatScroll.scrollTop = chatScroll.scrollHeight;
        }, 1200);
    }

    // ── welcome section class যোগ ────────────────────────────
    var welcomeSection = document.querySelector('.welcome-section-compact');
    if (welcomeSection) welcomeSection.classList.add('welcome-hero-v2');

    // ── 📱 মোবাইল ফ্লোটিং মেনুবার — টগল ───────────────────────
    var qtFabToggle = document.getElementById('qt-fab-toggle');
    var qtFabMenu = document.getElementById('qt-fab-menu');
    if (qtFabToggle && qtFabMenu) {
      qtFabToggle.addEventListener('click', function() {
        var isOpen = qtFabMenu.classList.toggle('open');
        qtFabToggle.classList.toggle('open', isOpen);
        qtFabToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      });
      qtFabMenu.querySelectorAll('button').forEach(function(btn) {
        btn.addEventListener('click', function() {
          qtFabMenu.classList.remove('open');
          qtFabToggle.classList.remove('open');
          qtFabToggle.setAttribute('aria-expanded', 'false');
        });
      });
      document.addEventListener('click', function(e) {
        if (!qtFabMenu.classList.contains('open')) return;
        if (qtFabMenu.contains(e.target) || qtFabToggle.contains(e.target)) return;
        qtFabMenu.classList.remove('open');
        qtFabToggle.classList.remove('open');
        qtFabToggle.setAttribute('aria-expanded', 'false');
      });
    }

})();
